window.products.push({"id":633087,"name":"Bissell Lightweight 3-in-1 Corded Lightweight Stick Vacuum, Silver","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41MdujywdjL._AC_SL1000_.jpg","description":"Give your floors a deeper clean with the Bissell 3-in-1 Vacuum Cleaner. This lightweight combination vacuum cleaner easily converts from stick to handheld — vacuum anywhere you need it. Whether cleaning your carpets, bare floors, stairs or upholstery, the Bissell 3-in-1 gets the job done. The 16' power cord helps you vacuum an entire room without having to unplug or move to a new power outlet. Plus, this upright vacuum weighs less than 4 lbs, making it extremely easy to use, even when turning around corners or working in tight spaces. The Bissell 3-in-1 is the perfect fit for small houses and cozy apartments.","images":["https://m.media-amazon.com/images/I/41MdujywdjL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Bissell","source_asin":"B008I31YBK","category_path":"Home & Kitchen"},"sku":"BM-633087","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B008I31YBK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B008I31YBK","price_pending":true,"merchant_ready":false});
